"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ANALYTICS,
  HEADLINE,
  MONTHLY_PATH,
  NATIONAL_ANNUAL,
  PARENT_LFP_2024,
  PRICE_GAP_PATH,
  SOURCE_NOTE,
  STATE_PRICES,
  type RegionId,
} from "@/data/us-childcare-price-vs-women-s-prime-age-lfp-2026-data";

type Panel =
  | "dual-index"
  | "yoy-diverge"
  | "monthly-path"
  | "parent-gap"
  | "state-ladder"
  | "price-lfp-scatter";

type SortMode = "price-desc" | "afford-desc" | "lfp-asc";

const COLORS = {
  childcare: "#b45309",
  allItems: "#64748b",
  lfp: "#0f766e",
  mothers: "#c2410c",
  fathers: "#1e40af",
  gapPos: "#dc2626",
  gapNeg: "#15803d",
  accent: "#1e3a5f",
  ne: "#1e40af",
  mw: "#64748b",
  south: "#ea580c",
  west: "#0d9488",
};

const REGION_COLOR: Record<RegionId, string> = {
  Northeast: COLORS.ne,
  Midwest: COLORS.mw,
  South: COLORS.south,
  West: COLORS.west,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

export function UsChildcarePriceVsWomenSPrimeAgeLfp2026Dashboard() {
