    [yearFrom],
  );

  const states = useMemo(() => {
    const filtered =
      region === "all"
        ? [...STATE_PRICES]
        : STATE_PRICES.filter((s) => s.region === region);
    return filtered.sort((a, b) => {
      if (sortMode === "afford-desc")
        return b.marriedCoupleAffordPct - a.marriedCoupleAffordPct;
      if (sortMode === "lfp-asc")
