                  <th className="py-2 pr-3 font-medium">Mothers 6???17</th>
                  <th className="py-2 font-medium">Women 25???54</th>
                </tr>
              </thead>
              <tbody>
                {NATIONAL_ANNUAL.filter(
                  (r) => r.year >= 2019 && r.mothersUnder6Lfp != null,
