                  unit="k"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Infant center price ($000)",
                    position: "insideBottom",
                    offset: -2,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="LFP"
                  domain={[70, 84]}
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Female 25???54 LFP proxy %",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[60, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value, name) => {
                    const n = typeof value === "number" ? value : Number(value);
                    if (name === "x" || name === "Infant $/k")
                      return [`$${n.toFixed(1)}k`, "Infant price"];
                    if (name === "y" || name === "LFP")
                      return [`${n.toFixed(1)}%`, "Female LFP proxy"];
                    return [n, String(name)];
                  }}
                  labelFormatter={(_, payload) => {
                    const p = payload?.[0]?.payload as
                      | { state?: string }
                      | undefined;
                    return p?.state ?? "";
                  }}
                />
                <Scatter name="States" data={scatterData}>
                  {scatterData.map((s) => (
                    <Cell key={s.abbr} fill={REGION_COLOR[s.region]} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

